'use strict';

// MODULES //

var umul = require( '@stdlib/number/uint32/base/mul' );
var umuldw = require( '@stdlib/number/uint32/base/muldw' );


// MAIN //

/**
* Multiplies two 64-bit unsigned integers.
*
* @private
* @param {ArrayLike<uinteger32>} a - 64-bit unsigned integer as [ high, low ]
* @param {ArrayLike<uinteger32>} b - 64-bit unsigned integer as [ high, low ]
* @returns {ArrayLike<uinteger32>} 64-bit unsigned integer product as [ high, low ]
*/
function multUint64( a, b ) {
	var la = a[1] >>> 0;
	var ha = a[0] >>> 0;
	var lb = b[1] >>> 0;
	var hb = b[0] >>> 0;

	var m1 = umul( la, hb ) >>> 0;
	var m2 = umul( ha, lb ) >>> 0;
	var p = umuldw( la, lb );

	p[ 0 ] = ( p[ 0 ] + m1 + m2 ) >>> 0;
	return p;
}


// EXPORTS //

module.exports = multUint64;
